+// Cube stage: scores = Q x K^T for every (head, row block) of one wave.
+__global__ __aicore__ void qk(GM_ADDR q, GM_ADDR k, GM_ADDR scores, int row0, int n) {
+    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIC_ONLY);
+    TPipe pipe;
+    auto tiling = Tiling(n, D);
+    Matmul<A, BTrans, CS, CS> mm;
+    mm.Init(&tiling, &pipe);
+    GlobalTensor<BF> qg, kg, sg;
+    qg.SetGlobalBuffer((__gm__ BF*)q);
+    kg.SetGlobalBuffer((__gm__ BF*)k);
+    sg.SetGlobalBuffer((__gm__ BF*)scores);
+    for (int item = GetBlockIdx(); item < HQ * W; item += GetBlockNum()) {
+        int h = item / W, b = item % W;
+        mm.SetTensorA(qg[(h * S + row0 + b * M) * D]);
+        mm.SetTensorB(kg[(h / (HQ / HK)) * S * D], true);
+        mm.IterateAll(sg[(h * WM + b * M) * n]);
+        mm.End();
+    }
+}
