+        PipeBarrier<PIPE_ALL>();
+        Cast(data, vec, RoundMode::CAST_NONE, padded);
+        Muls(data, data, SCALE, padded);
+        Exp(data, data, padded);
+        PipeBarrier<PIPE_ALL>();
+        for (int j = count; j < padded; ++j) data.SetValue(j, 0.0f);
+        PipeBarrier<PIPE_ALL>();
+        ReduceSum(scalar, data, work, n);
+        PipeBarrier<PIPE_ALL>();
+        float inv = 1.0f / scalar.GetValue(0);
