+    auto vt = torch::empty({HK, S, D}, q.options());
+    auto scores = torch::empty({HQ, WM, S}, q.options());
+    auto probs = torch::empty({HQ, WM, S}, q.options());
+    auto result = torch::empty({HQ, WM, D}, q.options().dtype(at::kFloat));
